function profileStorageKey(){return`${PROFILE_KEY}-${authSession?.user?.id||'guest'}`}
function emptyProfile(){return{name:'Estudiante',xp:0,completed:[],streak:0,lastStudyDate:null,badges:[],scores:{}}}
function loadProfile(){try{const saved=JSON.parse(localStorage.getItem(profileStorageKey()));return{name:saved?.name||'Estudiante',xp:Number(saved?.xp)||0,completed:Array.isArray(saved?.completed)?saved.completed:[],streak:Number(saved?.streak)||0,lastStudyDate:saved?.lastStudyDate||null,badges:Array.isArray(saved?.badges)?saved.badges:[],scores:saved?.scores&&typeof saved.scores==='object'?saved.scores:{}}}catch{return emptyProfile()}}
