function ensureDeviceHistory(target,devices){target.histories??={};target.historyIndexes??={};const legacy=Array.isArray(target.history)?target.history:[];devices.forEach(device=>{target.histories[device]??=device===target.activeDevice?[...legacy]:[];target.historyIndexes[device]??=target.histories[device].length})}
function writeConnectionIntro(device,isSwitch,write){write(`Conectando a ${device}...`);write('Conexión establecida.');write('');if(isSwitch){write('Cisco IOS Software, eClassVirtual Network Lab');write('Escribe ? para ver los comandos disponibles.')}else{write(`eClassVirtual Virtual PC — ${device}`);write('Usa ip <dirección>/<prefijo> <gateway> y ping <dirección>.')}write('')}
function bindCommandTerminal({input,terminal,clearButton,getState,getDevice,ensureHistory,execute,clearOutput}){input.addEventListener('keydown',event=>{ensureHistory();const target=getState(),device=getDevice(),history=target.histories[device];if(event.key==='Enter'){const value=input.value;if(value.trim())history.push(value);target.historyIndexes[device]=history.length;input.value='';execute(value)}else if(event.key==='ArrowUp'){event.preventDefault();if(target.historyIndexes[device]>0)input.value=history[--target.historyIndexes[device]]||''}else if(event.key==='ArrowDown'){event.preventDefault();if(target.historyIndexes[device]<history.length)input.value=history[++target.historyIndexes[device]]||''}});terminal.addEventListener('click',()=>input.focus());clearButton.addEventListener('click',()=>{clearOutput();input.focus()})}
function bindDeviceSelector(selector,dataKey,onSelect){document.querySelectorAll(selector).forEach(element=>element.addEventListener('click',()=>onSelect(element.dataset[dataKey])))}
function draftStorageKey(unit,labIndex){return`ecv-network-lab-draft-${authSession?.user?.id||'guest'}-${unit.id}-${labIndex}`}
function saveLocalDraft(unit,labIndex,payload){try{localStorage.setItem(draftStorageKey(unit,labIndex),JSON.stringify(payload));return true}catch{return false}}
function loadLocalDraft(unit,labIndex,legacyKey){try{const raw=localStorage.getItem(draftStorageKey(unit,labIndex))||(legacyKey?localStorage.getItem(legacyKey):null),saved=JSON.parse(raw);return saved?.state?saved:null}catch{return null}}
async function saveRemoteDraftRecord(unit,labIndex,draftState,attempts,usedHelp,startedAt){return apiRequest(`/drafts/${completionIndexFor(unit,labIndex)}`,{method:'PUT',body:{state:draftState,attempts,usedHelp,startedAt:new Date(startedAt).toISOString()}})}
function initials(name){return name.trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'ES'}
function validDisplayName(value){const name=String(value||'').trim().replace(/\s+/g,' ');if(name.length<2||name.length>30)return null;if(/[>#]$/.test(name)||/^(?:sw|pc|r)\d*[>#]/i.test(name)||/\(config(?:-[^)]+)?\)#?/i.test(name))return null;return name}
function recoveredDisplayName(){const user=authSession?.user||{};return validDisplayName(user.name)||validDisplayName(learner.name)||validDisplayName(user.email?.split('@')[0])||'Estudiante'}
function localDay(offset=0){const d=new Date();d.setDate(d.getDate()+offset);return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function updateStreak(){const today=localDay();if(learner.lastStudyDate===today)return;if(learner.lastStudyDate===localDay(-1))learner.streak+=1;else learner.streak=1;learner.lastStudyDate=today}
function renderProfile(){document.getElementById('studentName').textContent=learner.name;document.getElementById('studentXP').textContent=learner.xp;document.getElementById('studentStreak').textContent=learner.streak;document.getElementById('studentAvatar').textContent=initials(learner.name);renderBadges();renderLeaderboard()}
