const u3SwitchPort=()=>({mode:'access',accessVlan:1,allowedVlans:null,nativeVlan:1,adminUp:true,description:''});
const initialU3Switch=()=>({hostname:'SW1',mode:'user',context:null,vlans:{1:{name:'default'}},interfaces:{'GigabitEthernet0/1':u3SwitchPort(),'GigabitEthernet0/2':u3SwitchPort(),'GigabitEthernet0/3':u3SwitchPort()},saved:false,startupConfig:null});
const initialU3Router=()=>({hostname:'R1',mode:'user',context:null,interfaces:{'GigabitEthernet0/0':{adminUp:false,ip:null,mask:null,encapsulation:null,parent:null}},saved:false,startupConfig:null});
const initialU3State=()=>({activeDevice:'SW1',switch:initialU3Switch(),router:initialU3Router(),pcs:{PC1:{ip:null,mask:null,gateway:null,dns:null},PC2:{ip:null,mask:null,gateway:null,dns:null}},lastPing:null,observed:{SW1:{trunk:false,vlan:false},R1:{ipBrief:false,routes:false,runInterface:false}},histories:{SW1:[],R1:[],PC1:[],PC2:[]},historyIndexes:{SW1:0,R1:0,PC1:0,PC2:0}});
const u3AccessPort=(s,device)=>s.switch.interfaces[device==='PC1'?'GigabitEthernet0/1':'GigabitEthernet0/2'];
const u3TrunkPort=s=>s.switch.interfaces['GigabitEthernet0/3'];
const u3Subinterface=(s,vlan)=>s.router.interfaces[`GigabitEthernet0/0.${vlan}`];
const u3VlanNamed=(s,id,name)=>s.switch.vlans[id]?.name===name;
const u3SwitchingReady=(s,vlanA=10,vlanB=20)=>u3VlanNamed(s,vlanA,vlanA===10?'USERS':vlanA===30?'ADMIN':`VLAN${vlanA}`)&&u3VlanNamed(s,vlanB,vlanB===20||vlanB===40?'SERVERS':`VLAN${vlanB}`)&&u3AccessPort(s,'PC1').mode==='access'&&u3AccessPort(s,'PC1').accessVlan===vlanA&&u3AccessPort(s,'PC2').mode==='access'&&u3AccessPort(s,'PC2').accessVlan===vlanB&&u3TrunkPort(s).mode==='trunk';
function u3PrepareSwitch(s,vlanA=10,nameA='USERS',vlanB=20,nameB='SERVERS'){s.switch.vlans[vlanA]={name:nameA};s.switch.vlans[vlanB]={name:nameB};u3AccessPort(s,'PC1').mode='access';u3AccessPort(s,'PC1').accessVlan=vlanA;u3AccessPort(s,'PC2').mode='access';u3AccessPort(s,'PC2').accessVlan=vlanB;u3TrunkPort(s).mode='trunk'}
function u3PrepareRouter(s,vlanA=10,ipA='192.168.10.1',vlanB=20,ipB='192.168.20.1',wrongSecond=null){s.router.interfaces['GigabitEthernet0/0'].adminUp=true;s.router.interfaces[`GigabitEthernet0/0.${vlanA}`]={adminUp:true,ip:ipA,mask:'255.255.255.0',encapsulation:vlanA,parent:'GigabitEthernet0/0'};s.router.interfaces[`GigabitEthernet0/0.${vlanB}`]={adminUp:true,ip:ipB,mask:'255.255.255.0',encapsulation:wrongSecond??vlanB,parent:'GigabitEthernet0/0'}}
function u3PreparePcs(s,vlanA=10,vlanB=20){s.pcs.PC1={ip:`192.168.${vlanA}.10`,mask:'255.255.255.0',gateway:`192.168.${vlanA}.1`,dns:null};s.pcs.PC2={ip:`192.168.${vlanB}.20`,mask:'255.255.255.0',gateway:`192.168.${vlanB}.1`,dns:null}}
const u3SavedBoth=s=>s.switch.saved&&s.router.saved;
const u3SaveGoal={label:'Guardar SW1 y R1',detail:'Usa wr o copy run start en ambos equipos',test:s=>u3SavedBoth(s)};
const u3PingGoal=(ip='192.168.20.20')=>({label:'Comprobar enrutamiento',detail:`Ping exitoso PC1 → ${ip}`,test:s=>s.lastPing?.source==='PC1'&&s.lastPing?.target===ip&&s.lastPing?.ok});
