function validateCourseCatalog(courses,units){
 const unitIds=new Set(units.map(unit=>unit.id)),courseIds=new Set(),assignedUnits=new Set();
 for(const course of courses){
  if(!course.id||!course.vendor||!course.title||!course.examVersion||courseIds.has(course.id))throw new Error('Curso duplicado o incompleto');
  courseIds.add(course.id);
  const moduleIds=new Set(),usedUnits=new Set();
  for(const module of course.modules||[]){
   if(!module.id||!module.title||moduleIds.has(module.id))throw new Error(`Módulo inválido en ${course.id}`);
   moduleIds.add(module.id);
   for(const id of module.unitIds||[]){
    if(!unitIds.has(id)||usedUnits.has(id))throw new Error(`Unidad desconocida o repetida en ${course.id}: ${id}`);
    usedUnits.add(id);assignedUnits.add(id)
   }
  }
 }
 for(const id of unitIds)if(!assignedUnits.has(id))throw new Error(`Unidad publicada sin curso: ${id}`);
}
validateCourseCatalog(COURSE_CATALOG,UNIT_CATALOG);
