function courseForUnit(unit){return COURSE_CATALOG.find(course=>course.id===activeCourseId&&course.modules.some(module=>module.unitIds.includes(unit.id)))||COURSE_CATALOG.find(course=>course.modules.some(module=>module.unitIds.includes(unit.id)))}
