function completionIndexFor(unit,labIndex){return unit.completionStart+labIndex}
function unitCompletionIndexes(unit){return unit.labs.map((_,index)=>completionIndexFor(unit,index))}
function isLabComplete(unit,labIndex){return completedLabs.has(completionIndexFor(unit,labIndex))}
function isLabUnlocked(unit,labIndex){return !unit.sequential||labIndex===0||isLabComplete(unit,labIndex)||isLabComplete(unit,labIndex-1)}
function unitDoneCount(unit){return unit.labs.filter((_,index)=>isLabComplete(unit,index)).length}
function unitIsComplete(unit){return unitDoneCount(unit)===unit.labs.length}
function unitByNumber(number){return UNIT_CATALOG.find(unit=>unit.number===Number(number))}
function unitHasCapability(unitOrNumber,capability){const unit=typeof unitOrNumber==='object'?unitOrNumber:unitByNumber(unitOrNumber);return Boolean(unit?.capabilities?.includes(capability))}
function unitForCompletionIndex(index){return UNIT_CATALOG.find(unit=>index>=unit.completionStart&&index<unit.completionStart+unit.labs.length)}
