async function registerLabCompletion(unit,labIndex,{attempts=0,usedHelp=false,startedAt=Date.now()}={}){const completionIndex=completionIndexFor(unit,labIndex);if(isLabComplete(unit,labIndex))return{already:true,awarded:false,xp:0,newBadgeIds:[]};const duration=Math.max(0,Math.round((Date.now()-startedAt)/1000)),result=await awardRemote(completionIndex,attempts,usedHelp,duration);let newBadgeIds=[];if(result.awarded){completedLabs.add(completionIndex);learner.completed=[...completedLabs];learner.scores[completionIndex]=result.xp;learner.xp=result.total_xp;learner.streak=result.streak;newBadgeIds=unlockBadges();saveProfile()}await syncRemoteProgress(false);return{...result,already:!result.awarded,newBadgeIds}}
