function expandU3RouterCommand(raw){
 const cmd=raw.trim(),words=cmd.split(/\s+/),c=cmd.toLowerCase().replace(/\s+/g,' ');
 if(isAbbreviation(c,'enable',[2]))return'enable';
 if(isAbbreviation(c,'disable',[3]))return'disable';
 if(isAbbreviation(c,'configure terminal',[4,1]))return'configure terminal';
 if(isAbbreviation(c,'exit',[2]))return'exit';
 if(isAbbreviation(c,'end',[3]))return'end';
 const hostname=matchArg(c,'hostname',[4]);if(hostname!==null)return`hostname ${words.at(-1)}`;
 const intf=matchArg(c,'interface',[3]);if(intf!==null)return`interface ${words.at(-1)}`;
 const encapsulation=matchArg(c,'encapsulation dot1q',[3,3]);if(encapsulation!==null)return`encapsulation dot1Q ${encapsulation}`;
 if(isAbbreviation(c,'no encapsulation dot1q',[2,3,3]))return'no encapsulation dot1q';
 if(words.length>=3&&isAbbreviation(words.slice(0,2).join(' '),'ip address',[2,2]))return`ip address ${words.slice(2).join(' ')}`;
 if(isAbbreviation(c,'no ip address',[2,2,2]))return'no ip address';
 if(isAbbreviation(c,'no shutdown',[2,4]))return'no shutdown';
 if(isAbbreviation(c,'shutdown',[4]))return'shutdown';
 if(isAbbreviation(c,'show ip interface brief',[2,2,3,2]))return'show ip interface brief';
 if(isAbbreviation(c,'show ip route',[2,2,1]))return'show ip route';
 if(words.length===4&&isAbbreviation(words.slice(0,3).join(' '),'show running-config interface',[2,3,3]))return`show running-config interface ${words[3]}`;
 if(isAbbreviation(c,'show running-config',[2,3]))return'show running-config';
 if(isAbbreviation(c,'show startup-config',[2,3]))return'show startup-config';
 if(isAbbreviation(c,'write memory',[2,1])||(c.length>=2&&'write'.startsWith(c)))return'write memory';
 if(isAbbreviation(c,'copy running-config startup-config',[3,3,3]))return'copy running-config startup-config';
 if(isAbbreviation(c,'erase startup-config',[3,3])||isAbbreviation(c,'write erase',[2,1]))return'erase startup-config';
 return raw
}
